/* Immutable capture + one reusable compositor. No HTML interpretation or uploads. */
function createPhotoEditor103(dialog,onResult){
 const controls=document.createElement('section');controls.id='photoEditor103';controls.innerHTML='<label>프레임 <select id="photoFrame103"><option value="none">없음</option><option value="white">흰 여백</option><option value="instant">즉석사진</option><option value="navy">3NU 남색 테두리</option></select></label><div class="photoChecks103"><label><input type="checkbox" data-photo="place">장소명</label><label><input type="checkbox" data-photo="date">촬영 날짜</label><label><input type="checkbox" data-photo="logo">3NU 로고</label></div><label>한 줄 문구 <input id="photoCaption103" maxlength="60" placeholder="30자 이내" autocomplete="off"></label><button id="photoReset103" type="button">원본으로 되돌리기</button>';
 dialog.querySelector('footer').before(controls);const frame=controls.querySelector('select'),caption=controls.querySelector('#photoCaption103'),checks=[...controls.querySelectorAll('[data-photo]')],canvas=document.createElement('canvas'),logo=new Image();logo.src='assets/3nu-mark.svg';let source=null,meta=null,revision=0,pending=Promise.resolve(),count=0;
 function resetControls(){frame.value='none';caption.value='';checks.forEach(e=>e.checked=false)}
 function render(){if(!source)return Promise.resolve();const rev=++revision,src=source,opts={frame:frame.value,text:[...caption.value].slice(0,30).join(''),...Object.fromEntries(checks.map(e=>[e.dataset.photo,e.checked]))};caption.value=opts.text;const buttons=[...dialog.querySelectorAll('footer button')];buttons.forEach(e=>e.disabled=true);
 pending=(async()=>{if(opts.logo)try{await logo.decode()}catch{}if(rev!==revision||!source)return;const w=src.width,h=src.height,unit=Math.min(w,h),pad=Math.round(unit*(opts.frame==='none'?0:opts.frame==='instant'?.065:.035)),info=opts.text||opts.place||opts.date||opts.logo,bottom=Math.round(unit*(opts.frame==='instant'?.16:info?.09:0));canvas.width=w+2*pad;canvas.height=h+2*pad+bottom;const c=canvas.getContext('2d');c.fillStyle=opts.frame==='navy'?'#101d50':'#faf9f2';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(src,pad,pad);if(info){const text=[opts.place?meta.place:'',opts.date?meta.date:'',opts.text].filter(Boolean).join(' · '),size=Math.max(12,Math.round(unit*.024)),logoW=opts.logo?unit*.095:0,x=Math.max(pad,unit*.025),y=pad+h+bottom*.52+pad/2;c.fillStyle=opts.frame==='navy'?'#faf9f2':'#273a4c';c.textBaseline='middle';let font=size;c.font='500 '+font+'px sans-serif';const max=canvas.width-2*x-logoW-(opts.logo?unit*.03:0);while(c.measureText(text).width>max&&font>8){font--;c.font='500 '+font+'px sans-serif'}c.fillText(text,x,y,max);if(opts.logo&&logo.complete&&logo.naturalWidth){if(opts.frame==='navy'){c.fillStyle='#faf9f2';c.fillRect(canvas.width-x-logoW-4,y-unit*.026,logoW+8,unit*.052)}c.drawImage(logo,canvas.width-x-logoW,y-logoW*logo.naturalHeight/logo.naturalWidth/2,logoW,logoW*logo.naturalHeight/logo.naturalWidth)}}const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(rev!==revision||!source)return;if(blob){count++;onResult(blob,{width:canvas.width,height:canvas.height,meta,opts})}buttons.forEach(e=>e.disabled=false)})();return pending;}
 controls.addEventListener('change',e=>{if(e.target!==caption)render()});caption.addEventListener('input',render);controls.querySelector('button').onclick=()=>{resetControls();render()};
 return{async set(copy,metadata){this.clear();source=copy;meta=Object.freeze({...metadata});resetControls();await render()},clear(){revision++;if(source)source.width=source.height=0;source=null;meta=null;canvas.width=canvas.height=0;},get pending(){return pending},audit:()=>({source:source?{width:source.width,height:source.height}:null,meta,frame:frame.value,revision,compositions:count})};
}
